//★2026.08修复★ pixiv已把oauth迁移到Cloudflare，老的"域名替换成210.140.139.155再POST"会因
//HTTP/2的SNI↔Host严格校验被nginx以421拒绝；且GFW对*.pixiv.net的SNI直接重置。
//本函数用原始TLS套接字直连东京源站IP：不发SNI、不协商ALPN(h2)，手写HTTP/1.1报文，
//靠Host头路由到oauth虚拟主机（该证书为Google Trust Services公共证书，系统默认信任）。
function pxOauth(postBody) {
	const {java} = this;
	let time = java.timeFormatUTC(Date.now(),"yyyy-MM-dd'T'HH:mm:ss'+00:00'",8*60*60*1000);
	let hash = timemd5(time);
	let req = 'POST /auth/token HTTP/1.1\r\nHost: oauth.secure.pixiv.net\r\n'
		+'User-Agent: '+ua+'\r\n'
		+'content-type: application/x-www-form-urlencoded\r\n'
		+'x-client-time: '+time+'\r\nx-client-hash: '+hash+'\r\n'
		+'accept-language: '+a_l+'\r\napp-os: Android\r\napp-os-version: Android 14\r\napp-version: '+appv+'\r\n'
		+'Content-Length: '+postBody.length+'\r\nConnection: close\r\n\r\n'+postBody;
	let sf = Packages.javax.net.ssl.SSLSocketFactory.getDefault();
	let ips = ['210.140.139.155','210.140.139.152','210.140.139.158','210.140.139.161'];
	let sock = null, lastErr = '';
	for (let i = 0; i < ips.length; i++) {
		try {
			let addr = Packages.java.net.InetAddress.getByName(ips[i]);
			sock = sf.createSocket(addr, 443);
			sock.setSoTimeout(12000);
			let os = sock.getOutputStream();
			os.write(new Packages.java.lang.String(req).getBytes('UTF-8'));
			os.flush();
			let rd = new Packages.java.io.BufferedReader(new Packages.java.io.InputStreamReader(sock.getInputStream(),'UTF-8'));
			let sb = new Packages.java.lang.StringBuilder();
			let line;
			while ((line = rd.readLine()) != null) { sb.append(line); sb.append('\n'); }
			return String(sb.toString());
		} catch(e) {
			lastErr = e;
			try { if (sock != null) sock.close(); } catch(e2) {}
		}
	}
	throw lastErr == '' ? 'oauth直连失败：无可用IP' : lastErr;
}

