	let sf = Packages.javax.net.ssl.SSLSocketFactory.getDefault();
	let ips = ['210.140.139.155','210.140.139.152','210.140.139.158','210.140.139.161'];
	let sock = null, lastErr = '';
	for (let i = 0; i < ips.length; i++) {
